  for (let t = 1; t <= 4; t++) {
    const t0 = Date.now(); log(c.name, `envío (intento ${t}, ${secs}s)`);
    try {
      const r = await agnesGenerate(body, out, { tag: path.basename(path.dirname(OUT)) + "_avatar_" + c.name });
      if (r.ok) { log(c.name, "OK", Math.round((Date.now() - t0) / 1000) + "s"); return true; }
      log(c.name, "falló:", String(r.error).slice(0, 200));
    } catch (e) { log(c.name, "error:", String(e).slice(0, 300)); if (/REJECT/.test(String(e)) && t >= 2) break; }
  }
  return false;
}

